export type DomainErrorKind = 'validation' | 'not-found' | 'conflict';

/**
 * Base class for every business-rule violation raised by the domain.
 * The kind lets outer layers translate a failure without knowing each subtype.
 */
export abstract class DomainError extends Error {
  abstract readonly kind: DomainErrorKind;

  protected constructor(message: string) {
    super(message);
    this.name = new.target.name;
  }
}

export class ValidationError extends DomainError {
  readonly kind = 'validation';

  constructor(message: string) {
    super(message);
  }
}

export class NotFoundError extends DomainError {
  readonly kind = 'not-found';

  constructor(entity: string, id: string) {
    super(`${entity} '${id}' was not found`);
  }
}

export class InsufficientStockError extends DomainError {
  readonly kind = 'conflict';

  constructor(productId: string, requested: number, available: number) {
    super(`Insufficient stock for product '${productId}': requested ${requested}, available ${available}`);
  }
}

export class InvalidTransitionError extends DomainError {
  readonly kind = 'conflict';

  constructor(from: string, to: string) {
    super(`Order cannot move from '${from}' to '${to}'`);
  }
}

